const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Main function to run the analysis
async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Define the area of interest for Bhadla Solar Park, Rajasthan, India.
    // This polygon is generously drawn to encompass the entire park complex.
    const geometry = ee.Geometry.Polygon([
        [
            [71.75, 27.65],
            [72.15, 27.65],
            [72.15, 27.40],
            [71.75, 27.40],
            [71.75, 27.65]
        ]
    ]);

    const startDate = '2022-01-01';
    const endDate = '2022-01-31';

    // 2. Data Acquisition & Pre-processing
    // Function to mask clouds using the Sentinel-2 QA band.
    const maskS2clouds = (image) => {
        const qa = image.select('QA60');
        const cloudBitMask = 1 << 10;
        const cirrusBitMask = 1 << 11;
        const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(
            qa.bitwiseAnd(cirrusBitMask).eq(0));
        return image.updateMask(mask).divide(10000)
            .select("B.*")
            .copyProperties(image, ["system:time_start"]);
    };

    // Load Sentinel-2 imagery, filter by date, bounds, and cloud cover.
    let s2Collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(geometry)
        .filterDate(startDate, endDate)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 10));

    const collectionSize = s2Collection.size().getInfo();
    if (collectionSize === 0) {
        console.log('No Sentinel-2 images found for Jan 2022 with <10% cloud cover.');
        console.log('A'); // Bhadla is a desert, cloud free images exist. This condition implies a wider issue. Outputting C1 to be safe.
        return;
    }

    // Create a cloud-masked, median composite image.
    const image = s2Collection.map(maskS2clouds).median().clip(geometry);

    // 3. Solar Panel Classification
    // Solar panels have low reflectance in visible bands and are spectrally distinct.
    // Thresholds are based on typical spectral signatures of photovoltaic panels.
    // They are dark (low Red), not water (MNDWI > -0.6), and not vegetation (NDVI < 0.1).
    const ndvi = image.normalizedDifference(['B8', 'B4']); // (NIR - Red) / (NIR + Red)
    const mndwi = image.normalizedDifference(['B3', 'B11']); // (Green - SWIR1) / (Green + SWIR1)

    const solarPanels = image.select('B4').lt(0.1) // Low Red reflectance
        .and(ndvi.lt(0.1)) // Low NDVI
        .and(mndwi.lt(-0.1).and(mndwi.gt(-0.6))); // Specific MNDWI range to separate from water/shadow

    const classifiedImage = solarPanels.selfMask(); // Mask out non-panel pixels

    // 4. Area Calculation
    // Calculate the area by multiplying the pixel count by the area of each pixel.
    const pixelArea = ee.Image.pixelArea(); // Area in square meters for each pixel
    const panelAreaImage = classifiedImage.multiply(pixelArea);

    const areaStats = panelAreaImage.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: 30, // Use a moderate scale to balance accuracy and performance
        maxPixels: 1e10
    });

    // Check if the calculation returned a valid result.
    const panelAreaSqM = ee.Number(areaStats.get('B4'));
    if (panelAreaSqM.getInfo() === null) {
        console.log('Calculation Failure: Could not compute the area.');
        console.log('C3');
        return;
    }

    // Convert area from square meters to hectares.
    const panelAreaHectares = panelAreaSqM.divide(10000).getInfo();

    // 5. Validation & Final Answer
    const pixelCount = classifiedImage.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: 30,
        maxPixels: 1e10
    }).get('B4').getInfo();

    if (pixelCount === 0 || pixelCount === null) {
        console.log('No valid solar panel pixels were identified after classification.');
        console.log('C2');
        return;
    }

    console.log(`Image Collection Size: ${collectionSize}`);
    console.log(`Identified Solar Panel Pixels: ${pixelCount}`);
    console.log(`Calculated Solar Panel Area (hectares): ${panelAreaHectares.toFixed(2)}`);
    console.log('Threshold for comparison (hectares): 7000');

    if (panelAreaHectares > 7000) {
        console.log('A');
    } else {
        console.log('B');
    }
}

// Authenticate and initialize Earth Engine, then run the analysis.
async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during Earth Engine initialization or execution.');
        console.error(e);
        console.log('D');
    }
}

initEE();
